--@name P2M Mesh Tree
--@author AutoProp2Mesh
--@client

-- Generated by AutoProp2Mesh (the same chip works for every project; change PROJECT).
-- Place this chip where the model's origin should be:
-- the tree is parented to it. Downloads manifest.json, then every OBJ it lists,
-- and builds one anchor hologram per node (invisible, parented to its parent's
-- anchor) plus mesh holograms parented to the anchor.
--
-- Animate by moving anchors:  P2M.nodes["hull/torso"]:setLocalAngles(Angle(0, yaw, 0))
-- The only two things to edit: the repository's raw URL and the project folder inside it.
local REPO_URL = "https://raw.githubusercontent.com/USER/REPO/main/"
local PROJECT = "WF_BlenderExport"
local BASE_URL = REPO_URL .. PROJECT .. "/"
local HOLO_MODEL = "models/holograms/cube.mdl"

P2M = {nodes = {}, loaded = false}

local function get(url)
    local body
    while not http.canRequest() do coroutine.yield() end
    http.get(url, function(b, _, _, code)
            if code ~= 200 then
                print("P2M: HTTP " .. tostring(code) .. " for " .. url)
                body = false
            else
                body = b
            end
        end,
        function(reason) body = false print("P2M: failed to download " .. url .. ": " .. tostring(reason)) end)
    while body == nil do coroutine.yield() end
    return body
end

local function build(node, parent, path, nocull)
    path = path == "" and node.name or (path .. "/" .. node.name)
    while not hologram.canSpawn() do coroutine.yield() end
    local anchor = hologram.create(parent:getPos(), parent:getAngles(), HOLO_MODEL)
    anchor:setNoDraw(true)
    anchor:setParent(parent)
    anchor:setLocalPos(Vector(node.pos[1], node.pos[2], node.pos[3]))
    anchor:setLocalAngles(Angle(node.ang[1], node.ang[2], node.ang[3]))
    P2M.nodes[path] = anchor

    if node.file then
        local body = get(BASE_URL .. node.file)
        if body then
            local meshes = mesh.createFromObj(body, true, true)
            local ok, mat = pcall(material.load, node.material)
            local c = node.color
            for _, msh in pairs(meshes) do
                for _, mode in ipairs(nocull and {0, 1} or {0}) do
                    while not hologram.canSpawn() do coroutine.yield() end
                    local h = hologram.create(anchor:getPos(), anchor:getAngles(), HOLO_MODEL)
                    h:setMesh(msh)
                    if nocull then h:setCullMode(mode) end
                    if ok and mat then h:setMeshMaterial(mat) end
                    h:setColor(Color(c[1], c[2], c[3], c[4]))
                    h:setParent(anchor)
                    h:setLocalPos(Vector(0, 0, 0))
                    h:setLocalAngles(Angle(0, 0, 0))
                end
            end
        end
    end
    for _, child in ipairs(node.children or {}) do
        build(child, anchor, path, nocull)
    end
end

local function load()
    local text = get(BASE_URL .. "manifest.json")
    if not text then return end
    local manifest = json.decode(text)
    print("P2M: loading " .. manifest.name)
    for _, node in ipairs(manifest.nodes) do
        build(node, chip(), "", manifest.nocull)
    end
    P2M.loaded = true
    print("P2M: done")
end

-- Needs the client to grant the permissions Starfall asks for (http, mesh, material, hologram, parenting).
local co = coroutine.create(load)
hook.add("think", "p2m_loader", function()
    if coroutine.status(co) == "dead" then hook.remove("think", "p2m_loader") return end
    if quotaAverage() < quotaMax() * 0.5 then
        coroutine.resume(co)
    end
end)
